Here's a comprehensive X++ script to create a custom REST service in Dynamics AX (now Dynamics 365 Finance and Operations):

```x++
/// <summary>
/// Custom REST Service Class for handling REST API operations
/// </summary>
public class MyCustomRestService extends ServiceController
{
    // Private constants
    private const str ServiceName = 'MyCustomRestService';

    /// <summary>
    /// Constructor for the REST service
    /// </summary>
    public void new()
    {
        super();
    }

    /// <summary>
    /// GET method to retrieve data
    /// </summary>
    /// <param name = "_id">Unique identifier for the resource</param>
    /// <returns>Container with retrieved data</returns>
    [HttpAttribute(HttpMethod::GET)]
    public container get(str _id)
    {
        container result;

        try
        {
            // Perform data retrieval logic
            MyCustomTable myTable = MyCustomTable::findById(_id);

            if (myTable)
            {
                result = [
                    myTable.RecId,
                    myTable.Name,
                    myTable.Description
                ];
            }
            else
            {
                // Handle not found scenario
                throw error("@SYS_ServiceNotFound");
            }
        }
        catch (Exception::Error)
        {
            // Log error
            SysServiceLog::insertLog(
                ServiceName, 
                "GET", 
                _id, 
                errorGetLast()
            );

            // Rethrow or handle as needed
            throw;
        }

        return result;
    }

    /// <summary>
    /// POST method to create new resource
    /// </summary>
    /// <param name = "_payload">JSON payload for creating resource</param>
    /// <returns>Container with created resource details</returns>
    [HttpAttribute(HttpMethod::POST)]
    public container create(str _payload)
    {
        container result;

        try
        {
            // Parse JSON payload
            Map payloadMap = JsonSerializer::parseString(_payload);

            // Create new record
            MyCustomTable myTable = MyCustomTable::newRecord();
            myTable.Name = payloadMap.getValue('Name');
            myTable.Description = payloadMap.getValue('Description');

            // Validate and save
            myTable.validateWrite();
            myTable.save();

            // Prepare result
            result = [
                myTable.RecId,
                myTable.Name,
                myTable.Description
            ];
        }
        catch (Exception::Error)
        {
            // Log error
            SysServiceLog::insertLog(
                ServiceName, 
                "POST", 
                _payload, 
                errorGetLast()
            );

            // Rethrow or handle as needed
            throw;
        }

        return result;
    }

    /// <summary>
    /// PUT method to update existing resource
    /// </summary>
    /// <param name = "_id">Unique identifier for the resource</param>
    /// <param name = "_payload">JSON payload for updating resource</param>
    /// <returns>Container with updated resource details</returns>
    [HttpAttribute(HttpMethod::PUT)]
    public container update(str _id, str _payload)
    {
        container result;

        try
        {
            // Find existing record
            MyCustomTable myTable = MyCustomTable::findById(_id);

            if (myTable)
            {
                // Parse JSON payload
                Map payloadMap = JsonSerializer::parseString(_payload);

                // Update fields
                myTable.Name = payloadMap.getValue('Name');
                myTable.Description = payloadMap.getValue('Description');

                // Validate and save
                myTable.validateWrite();
                myTable.save();

                // Prepare result
                result = [
                    myTable.RecId,
                    myTable.Name,
                    myTable.Description
                ];
            }
            else
            {
                // Handle not found scenario
                throw error("@SYS_ServiceNotFound");
            }
        }
        catch (Exception::Error)
        {
            // Log error
            SysServiceLog::insertLog(
                ServiceName, 
                "PUT", 
                _id + ':' + _payload, 
                errorGetLast()
            );

            // Rethrow or handle as needed
            throw;
        }

        return result;
    }

    /// <summary>
    /// DELETE method to remove resource
    /// </summary>
    /// <param name = "_id">Unique identifier for the resource</param>
    /// <returns>Boolean indicating successful deletion</returns>
    [HttpAttribute(HttpMethod::DELETE)]
    public boolean delete(str _id)
    {
        boolean result = false;

        try
        {
            // Find existing record
            MyCustomTable myTable = MyCustomTable::findById(_id);

            if (myTable)
            {
                // Delete record
                myTable.delete();
                result = true;
            }
            else
            {
                // Handle not found scenario
                throw error("@SYS_ServiceNotFound");
            }
        }
        catch (Exception::Error)
        {
            // Log error
            SysServiceLog::insertLog(
                ServiceName, 
                "DELETE", 
                _id, 
                errorGetLast()
            );

            // Rethrow or handle as needed
            throw;
        }

        return result;
    }

    /// <summary>
    /// Generates service metadata
    /// </summary>
    /// <returns>Service description</returns>
    public static ServiceDescription serviceDescription()
    {
        ServiceDescription desc = new ServiceDescription(ServiceName);

        // Define service methods
        desc.addMethod('get', 
            'Retrieves a specific resource', 
            ['_id:str'], 
            'container');

        desc.addMethod('create', 
            'Creates a new resource', 
            ['_payload:str'], 
            'container');

        desc.addMethod('update', 
            'Updates an existing resource', 
            ['_id:str', '_payload:str'], 
            'container');

        desc.addMethod('delete', 
            'Deletes a specific resource', 
            ['_id:str'], 
            'boolean');

        return desc;
    }
}
```

To complete the REST service implementation, you'll also need to:

1. Create the corresponding table (MyCustomTable in this example)
2. Configure service endpoints in the AOT
3. Set up proper security and role-based access

